// Open work invites perspectives; previous experiences support the discussion.
const legacyRender=render;
let conversationTab='All conversations',conversationSearch='',threadOpen=false;
let discussionReplies=load('wwk-discussion-replies',[]),localRequests=load('wwk-requests',[]);
const mainPost={id:'maya-study',author:'maya',status:'Open for input',topic:'Patient experience',title:'Would patients know which instructions to follow before their appointment?',intro:'Hi, I’m Maya, a designer new to Aster. I’m working on the online page patients use to prepare for an appointment. Before we test it with patients, could you review the page and our draft questions?',need:'Feedback on the page and study tasks · Similar experiences from your work',replies:5};
const otherPosts=[{id:'confirmation',author:'christine',status:'Exploring a question',topic:'Patient experience',title:'What helps someone recognize an appointment confirmation?',intro:'Hi, I’m Christine from patient services. Some callers describe their appointment differently from the name in their confirmation message. I’m collecting examples of how other teams make service names recognizable. Have you worked on something similar?',need:'Examples from other services · Content perspectives',replies:0},{id:'handover-work',author:'jonas',status:'Open for input',topic:'Team learning',title:'What context do you wish you had when taking over a project?',intro:'Hi, I’m Jonas from engineering. A team taking over our work could find the final design but not why we chose it. I’m drafting a handover template that records the decision, alternatives and constraints. What would your team need to understand before continuing someone else’s work?',need:'Your handover experiences · Missing context',replies:0}];
const threadDialog=document.createElement('dialog');threadDialog.id='materials-dialog';document.body.appendChild(threadDialog);
const requestDialog=document.createElement('dialog');requestDialog.id='request-dialog';requestDialog.innerHTML=`<form id="request-form"><div class="dialog-top"><span class="eyebrow">OPEN YOUR WORK TO OTHER PERSPECTIVES</span><button type="button" class="icon-button" data-talk="close-request" aria-label="Close new conversation">×</button></div><h2>What are you working on?</h2><p class="muted">Give colleagues enough context to decide how they can help.</p><label>A clear question<input name="title" required placeholder="What would you like another perspective on?"></label><label>Introduce the work and why it matters<textarea name="context" required placeholder="Hi, I’m working on… It affects… We noticed…"></textarea></label><label>What input would help?<textarea name="ask" required placeholder="What can colleagues still influence? What experience would be useful?"></textarea></label><label>Link to work people can review (optional)<input name="link" type="url" placeholder="https://…"></label><p class="form-note">Fictional demo. Your conversation stays in this browser; colleagues are not notified.</p><button class="primary" type="submit">Start conversation ↗</button></form>`;document.body.appendChild(requestDialog);
function postCard(p){return `<article class="post-card"><div class="post-byline">${avatar(p.author)}<div><strong>${people[p.author].name}</strong><small>${people[p.author].role} · ${p.author==='maya'?'Patient portal':'Across Aster'}</small></div><span class="post-time">${p.id==='maya-study'?'Today':'This week'}</span></div><div class="post-meta"><span class="badge perspective">${escape(p.status)}</span><span>${escape(p.topic)}</span></div><h2><button data-thread="${p.id}">${escape(p.title)}</button></h2><p>${escape(p.intro)}</p><div class="post-ask"><span>LOOKING FOR</span>${escape(p.need)}</div>${p.id==='maya-study'?'<div class="attachment-preview"><button data-material="portal">▧ <span>Preparation page · current & early idea<small>Review the work</small></span> ↗</button><button data-material="tasks">▤ <span>Draft study tasks<small>What we plan to ask participants</small></span> ↗</button></div>':''}<div class="post-bottom"><button class="text-button" data-thread="${p.id}">◌ ${p.replies+discussionReplies.filter(r=>(r.post||'maya-study')===p.id).length} contributions · Join the conversation →</button>${p.id==='maya-study'?'<span class="small-update">✓ Maya shared an update</span>':''}</div></article>`}
function conversationHome(){threadOpen=false;$('#crumb').textContent='Open conversations';$('#content').innerHTML=`<div class="page-heading"><div><span class="eyebrow">GOOD WORK STARTS WITH ANOTHER PERSPECTIVE</span><h1>What are you working on?</h1><p>Open a question. Share your experience. Help a colleague see something differently.</p></div><button class="primary" data-talk="new">Start a conversation <span>＋</span></button></div><div class="conversation-layout"><section><div class="search"><span>⌕</span><input id="conversation-search" aria-label="Search conversations" placeholder="Find a question, topic or colleague…" value="${escape(conversationSearch)}"></div><div class="filters">${['All conversations','Open for input','Updates'].map(f=>`<button class="filter ${conversationTab===f?'active':''}" data-conversation-filter="${f}">${f}</button>`).join('')}</div><div id="posts"></div></section><div class="conversation-aside"><div class="welcome-panel"><span class="spark">✳</span><h3>Your experience might help<br>another team.</h3><p>You don’t need to know everyone—or have the final answer. A question, an example or a different way of looking can help.</p><div class="divider"></div><span class="eyebrow">YOUR CURRENT WORK</span><h4>Appointment preparation</h4><p>You’re exploring as Maya, planning how to test the appointment-preparation page.</p><button class="text-button" data-thread="maya-study">View Maya’s conversation ↗</button></div><div class="small-panel"><h4>Bring an experience into the conversation</h4><p>Find something a colleague has already tried, learned or questioned.</p><button class="text-button" data-nav="experiences">Explore shared experiences ↗</button></div><p class="demo-label">Fictional company and conversations.<br>Replies are saved in this browser only.</p></div></div>`;drawPosts()}
function drawPosts(){const posts=[mainPost,...localRequests,...otherPosts].filter(p=>(conversationTab!=='Open for input'||p.status==='Open for input')&&(conversationTab!=='Updates'||p.id==='maya-study')&&(p.title+' '+p.intro+' '+people[p.author].name).toLowerCase().includes(conversationSearch.toLowerCase()));$('#posts').innerHTML=posts.length?posts.map(postCard).join(''):'<div class="empty">No conversations match. Try another search or filter.</div>'}
function personLine(key,extra=''){return `${avatar(key)}<div><strong>${people[key].name}</strong><small>${people[key].role}${extra?' · '+extra:''}</small></div>`}
function sampleReply(key,text,extra='',nested=''){return `<article class="reply"><div class="post-byline">${personLine(key,extra)}</div><p>${text}</p>${nested}</article>`}
function openThread(id){const p=[mainPost,...otherPosts,...localRequests].find(p=>p.id===id);if(!p)return;threadOpen=true;$('#crumb').textContent='Conversation';$('#content').innerHTML=`<button class="back-link" data-talk="back">← All conversations</button><div class="thread-layout"><article class="thread-main"><div class="post-byline">${personLine(p.author,p.author==='maya'?'New to Aster':'')}<span class="post-time">${p.id==='maya-study'?'Today':'This week'}</span></div><div class="post-meta"><span class="badge perspective">${escape(p.status)}</span><span>${escape(p.topic)}</span></div><h1>${escape(p.title)}</h1><div class="thread-copy"><p>${escape(p.intro)}</p>${p.id==='maya-study'?`<h3>What we’re working on</h3><p>Our patient portal is a website where patients can view appointments and information about their visit. Its preparation page combines instructions for first consultations and follow-up appointments. Patients have to work out which sections apply to them. I’m planning sessions where we watch people use the page, so we can understand where they become unsure.</p><h3>Why we’re asking</h3><p>Christine’s patient-services team receives calls asking which instructions apply. Alex previously tested a version with simpler wording: some participants understood the sentences but still could not identify the information for their appointment. We need to investigate how patients find the right section, as well as whether they understand its wording.</p><h3>Here’s the work you can review</h3><div class="attachment-preview"><button data-material="portal">▧ <span>Preparation page · current & early idea<small>Compare two sample screens</small></span> ↗</button><button data-material="tasks">▤ <span>Draft study tasks<small>Read the questions we plan to ask</small></span> ↗</button></div><h3>What input would help?</h3><ul><li>What context or explanation seems to be missing?</li><li>Have you encountered a similar problem in another service?</li><li>Do our draft questions tell participants where to look, or miss something they would need in real life?</li></ul><p>You don’t need healthcare expertise to contribute. Perspectives from content, accessibility, customer support, engineering or other services could help us question our assumptions.</p><div class="context-box"><strong>Still open to change</strong><br>The attached design is an early idea, not an agreed solution. Your input can change the page, the questions we ask and where the study starts. We are asking about finding and understanding information; clinical staff must review any medical instructions separately.</div><p>I’ll share the revised plan and explain what changed. — Maya</p>`:`<h3>What input would help?</h3><p>${escape(p.need)}</p>${p.id==='confirmation'?'<div class="context-box"><strong>Example we are reviewing</strong><br>A confirmation says “First consultation,” while a patient might describe the same visit as “my first appointment.” What wording or extra explanation would help them connect the two? I’m looking for comparable examples, not a decision about clinical terminology.</div>':p.id==='handover-work'?'<div class="context-box"><strong>Draft template to review</strong><br>1. What did we decide? 2. Why? 3. What alternatives did we consider? 4. What constraints mattered? 5. What could make us revisit the decision?<br><br>Would this give your team enough context? What would you add or remove?</div>':''}${p.link?`<a class="inline-link" href="${escape(p.link)}" target="_blank" rel="noopener noreferrer">Review linked work ↗</a>`:''}`}</div><div class="discussion-heading"><h2>The conversation</h2><span>${p.id==='maya-study'?5+discussionReplies.filter(r=>(r.post||'maya-study')===id).length:discussionReplies.filter(r=>r.post===id).length} contributions</span></div><div class="discussion">${p.id==='maya-study'?sampleReply('christine','This is a useful question for patient services, too. Some callers read the whole page and then ask us to confirm which section is theirs. Could participants start with the message confirming their appointment, rather than being taken directly to the preparation page? That would let us see whether they recognize the appointment name and find the right link.','Patient services',`<div class="nested-reply"><div class="post-byline">${personLine('maya','Author')}</div><p>Good point. My draft tells people to open the preparation page, so it skips how they get there. Do callers use the name written in their confirmation, or describe the appointment differently?</p><p class="reply-followup"><strong>Christine:</strong> Often another way. Let’s review a few examples together before we write the task.</p></div>`)+sampleReply('alex','We tried shorter wording in an earlier study. Some people could explain the instructions but still did not know which ones were for their appointment. I’ve linked the account below. It may help you test finding the right information separately from understanding the words.','Product design',`<button class="linked-experience" data-open="instructions"><span class="badge">Previous experience</span><strong>Patients understood the words, but weren’t sure which instructions applied.</strong><span>Read Alex’s account ↗</span></button>`)+sampleReply('jonas','We originally put all appointment instructions on one page so staff would not have to update several separate pages. The portal can now identify a patient’s appointment type, so we could explore showing only the relevant instructions. I can help check whether that is feasible. That explains why the page looks this way, but it does not mean we have to keep it.','Engineering')+`<section class="outcome-update"><span class="eyebrow">AUTHOR UPDATE · WHAT CHANGED</span><h3>Our study will start with the appointment-confirmation message.</h3><p><strong>Maya:</strong> Thanks, everyone. The revised plan starts with the appointment-confirmation message and asks participants to find what they need before their visit. In my previous design work, I learned to describe the person’s goal without naming the buttons or sections. I’m using that approach here, so our question does not give away where to look.</p><p>Christine will help make the appointment scenario realistic. Alex’s account explains why we should test more than the wording. Jonas will check whether the portal could show instructions for a specific appointment type. We have changed the plan; we have not tested it with patients yet.</p><button class="text-button" data-material="revised">Read the revised study plan ↗</button><small>Illustrative outcome for this fictional scenario—not a real study result.</small></section>`:''}${discussionReplies.filter(r=>(r.post||'maya-study')===id).map(r=>sampleReply('maya',escape(r.text),'Your demo contribution',r.experience?`<button class="linked-experience" data-open="${r.experience}"><strong>${escape(entries.find(e=>e.id===r.experience)?.title)}</strong><span>Connected experience ↗</span></button>`:'')).join('')}</div><form id="reply-form" data-post="${p.id}" class="reply-composer"><div class="post-byline">${personLine('maya','You')}</div><label>Add a perspective<textarea name="reply" required placeholder="Share an experience, ask a question, or explain what you see differently…"></textarea></label><label class="attach-label">Connect a previous experience (optional)<select name="experience"><option value="">No experience attached</option>${entries.map(e=>`<option value="${e.id}">${escape(e.title)}</option>`).join('')}</select></label><div class="composer-bottom"><small>Demo only · Saved in this browser, not sent to colleagues.</small><button class="primary" type="submit">Add to conversation ↗</button></div></form></article><aside class="thread-context"><span class="eyebrow">ABOUT THIS WORK</span><h3>Patient portal</h3><p>Helping patients prepare for their first appointment.</p><dl><dt>Stage</dt><dd>Planning research</dd><dt>Team</dt><dd>Product & patient experience</dd><dt>Looking for</dt><dd>Questions, examples and feedback</dd></dl><div class="divider"></div><h4>Different experience is welcome</h4><p>You can contribute without joining the project or committing to mentoring.</p><button class="text-button" data-nav="people">Meet colleagues ↗</button></aside></div>`;window.scrollTo(0,0)}
function showMaterial(kind){const portal=kind==='portal';threadDialog.innerHTML=`<div class="dialog-inner"><div class="dialog-top"><span class="eyebrow">${portal?'WORK TO REVIEW · FICTIONAL PROTOTYPE':'STUDY PREPARATION · FICTIONAL DOCUMENT'}</span><button class="icon-button" data-talk="close-material" aria-label="Close material">×</button></div><h2>${portal?'Appointment preparation page':kind==='revised'?'Revised usability-study plan':'Draft usability-study tasks'}</h2>${portal?`<div class="material-tabs"><button class="filter active" data-page-version="before">Current page</button><button class="filter" data-page-version="proposed">Proposed direction</button></div><div id="portal-preview"></div><p class="muted">These fictional screens illustrate how information could be grouped. The early idea has not been tested or approved, and contains no medical preparation instructions.</p>`:kind==='revised'?`<div class="document-preview"><span class="eyebrow">UPDATED AFTER THE CONVERSATION</span><h3>Research question</h3><p>Starting from an appointment-confirmation message, can patients find and understand the preparation information for their own visit?</p><h3>Starting material</h3><div class="context-box"><strong>Sample appointment confirmation</strong><br>Your first consultation is on 12 November at 10:00 at Aster clinic, Reception A. Before your visit, open the preparation information in your patient portal.<br><br>In a real study, participants would receive the actual message and working link. This prototype uses a fictional example.</div><h3>Revised task</h3><p>“Imagine you have an upcoming first appointment. Using this appointment-confirmation message, show us how you would find out what to do before your visit.”</p><h3>What we’ll observe</h3><p>The terms people recognize; where they look; which information they select; what they remain uncertain about. We’ll avoid naming the page or sections in the task.</p><h3>How colleagues shaped it</h3><ul><li>Christine: start with the confirmation and check the scenario is realistic.</li><li>Alex: separate understanding the text from identifying relevance.</li><li>Jonas: check whether appointment-specific content is now feasible.</li><li>Maya: use a goal-based task from her previous research practice.</li></ul><p>Next: review with the researcher and clinical specialist before testing. No results have been collected.</p></div>`:`<div class="document-preview"><span class="eyebrow">DRAFT · OPEN FOR FEEDBACK</span><h3>What we want to learn</h3><p>Whether the appointment-preparation page helps patients understand what to do before their visit.</p><p>Participants will imagine they have booked a first consultation. This draft starts them on the preparation page, so it does not yet test whether they can get there from the confirmation message.</p><h3>Task 1</h3><p>“Open the preparation page and find the section for your appointment.”</p><h3>Task 2</h3><p>“Read the checklist. What would you do before your appointment?”</p><h3>Task 3</h3><p>“Was any information difficult to understand?”</p><div class="context-box">Maya’s question for colleagues: Are these tasks realistic? Are we telling participants where to look instead of finding out how they would get there themselves? What information would they need before starting?</div></div>`}</div>`;threadDialog.showModal();if(portal)drawPortal('before')}
function drawPortal(version){$('#portal-preview').innerHTML=`<div class="portal-mock"><div class="portal-brand">a. <span>Aster patient portal</span></div><small>Appointments / Preparation</small><h3>${version==='before'?'Prepare for your appointment':'Your first consultation'}</h3>${version==='before'?'<p>Find preparation information for your upcoming visit.</p><div class="portal-box"><strong>Before you arrive</strong><p>Check the date and location in your confirmation.</p></div><div class="portal-box"><strong>First consultation</strong><p>Have your appointment confirmation available when you arrive.</p></div><div class="portal-box"><strong>Follow-up appointments</strong><p>Bring the list of questions you agreed to discuss at your previous visit.</p></div>':'<div class="portal-appointment"><strong>Your appointment</strong><p>First consultation · 12 November · 10:00<br>Aster clinic · Reception A</p></div><p>These instructions are for your first consultation. Follow-up preparation is shown separately for patients with a follow-up booking.</p><div class="portal-box"><strong>Before your visit</strong><p>Check the date and location, and have your appointment confirmation available.</p></div><p class="muted">Something doesn’t match your confirmation? Contact patient services.</p>'}<span class="demo-label">Fictional example · No patient data</span></div>`;document.querySelectorAll('[data-page-version]').forEach(b=>b.classList.toggle('active',b.dataset.pageVersion===version))}
render=function(){document.querySelector('nav [data-nav="explore"]').innerHTML='<span>◌</span> Open conversations';if(!document.querySelector('nav [data-nav="experiences"]')){const n=document.createElement('button');n.dataset.nav='experiences';n.innerHTML='<span>◉</span> Shared experiences';document.querySelector('nav').insertBefore(n,document.querySelector('nav [data-nav="project"]'))}if(view==='explore'){document.querySelectorAll('nav [data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav==='explore'));conversationHome()}else if(view==='experiences'){view='explore';legacyRender();view='experiences';$('#crumb').textContent='Shared experiences';document.querySelectorAll('nav [data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav==='experiences'));$('#content .page-heading h1').textContent='Experience worth bringing into the conversation.';$('#content .page-heading p').textContent='Explore what colleagues have tried, learned and questioned.';$('.project-banner')?.remove();}else{legacyRender();if(view==='project'){$('#content').insertAdjacentHTML('afterbegin','<div class="project-thread-link"><span>This project has an open conversation across teams.</span><button class="text-button" data-thread="maya-study">View discussion & update ↗</button></div>')}}};
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.thread)openThread(b.dataset.thread);if(b.dataset.material)showMaterial(b.dataset.material);if(b.dataset.pageVersion)drawPortal(b.dataset.pageVersion);if(b.dataset.conversationFilter){conversationTab=b.dataset.conversationFilter;conversationHome()}if(b.dataset.talk==='new')requestDialog.showModal();if(b.dataset.talk==='close-request')requestDialog.close();if(b.dataset.talk==='close-material')threadDialog.close();if(b.dataset.talk==='back')conversationHome();if(b.dataset.nav==='explore')window.scrollTo(0,0)});
document.addEventListener('input',ev=>{if(ev.target.id==='conversation-search'){conversationSearch=ev.target.value;drawPosts()}});
document.addEventListener('submit',ev=>{if(ev.target.id==='reply-form'){ev.preventDefault();const f=new FormData(ev.target),text=f.get('reply').trim();if(!text)return;const id=ev.target.dataset.post;discussionReplies.push({post:id,text,experience:f.get('experience')});localStorage.setItem('wwk-discussion-replies',JSON.stringify(discussionReplies));openThread(id);document.querySelector('.reply-composer').scrollIntoView({block:'center',behavior:'smooth'});toast('Added to the demo conversation in this browser')}if(ev.target.id==='request-form'){ev.preventDefault();const f=new FormData(ev.target);if(!f.get('title').trim()||!f.get('context').trim()||!f.get('ask').trim())return;const raw=f.get('link').trim();const link=/^https?:\/\//i.test(raw)?raw:'';localRequests.unshift({id:'request-'+Date.now(),author:'maya',status:'Open for input',topic:'Across teams',title:f.get('title').trim(),intro:f.get('context').trim(),need:f.get('ask').trim(),link,replies:0});localStorage.setItem('wwk-requests',JSON.stringify(localRequests));requestDialog.close();ev.target.reset();view='explore';conversationTab='All conversations';conversationSearch='';render();toast('Conversation created in this browser')}});
threadDialog.addEventListener('click',e=>{if(e.target===threadDialog)threadDialog.close()});requestDialog.addEventListener('click',e=>{if(e.target===requestDialog)requestDialog.close()});
render();
